entries[51564] = { ["name"] = "Flutwellen", ["text"] = "Der Einsatz von 'Springflut' gewährt 2 Stapel von 'Flutwellen'. 'Flutwellen' verringert die Zauberzeit Eurer nächsten 'Welle der Heilung' oder 'Kettenheilung' um 20% oder erhöht die Chance auf einen kritischen Effekt mit Eurer nächsten 'Heilende Woge' um 30%." }
entries[51568] = { ["name"] = "Dunkle Chitinwächterstiefel", ["text"] = "Wirken in 2 sek.\nReagenzien:\nNerubisches Chitin (25), Kristallisiertes Wasser (6)\nOptionale Reagenzien:\n[] (#48)\nBerufsausbilder:\nLederverarbeitung von Nordend (25)\nKosten:\n1\n\nDunkle Chitinwächterstiefel\nWird beim Anlegen gebunden\nFüße Leder\n4 Rüstung\n+3 [Beweglichkeit oder Intelligenz]+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nHaltbarkeit 65 / 65\n29" }
entries[51569] = { ["name"] = "Dunkle arktische Gamaschen", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSchweres boreanisches Leder (6), Kristallisierter Schatten (4)\nOptionale Reagenzien:\n[] (#48)\nBerufsausbilder:\nLederverarbeitung von Nordend (20)\nKosten:\n75\n\nDunkle arktische Gamaschen\nWird beim Anlegen gebunden\nBeine Leder\n6 Rüstung\n+3 [Beweglichkeit oder Intelligenz]+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nHaltbarkeit 100 / 100\n29\n\nBoreanische Umarmung (0/8)\nArktischer Gürtel\nArktische Stiefel\nArktischer Brustschutz\nArktische Handschuhe\nArktische Gamaschen\nArktische Schulterpolster\nArktischer Helm\nArktische Handgelenksschützer" }
entries[51570] = { ["name"] = "Dunkler arktischer Brustharnisch", ["text"] = "Wirken in 2 sek.\nReagenzien:\nSchweres boreanisches Leder (5), Kristallisierter Schatten (5)\nOptionale Reagenzien:\n[] (#49)\nBerufsausbilder:\nLederverarbeitung von Nordend (20)\nKosten:\n75\n\nDunkler arktischer Brustharnisch\nWird beim Anlegen gebunden\nBrust Leder\n7 Rüstung\n+3 [Beweglichkeit oder Intelligenz]+8 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nHaltbarkeit 140 / 140\n29\n\nBoreanische Umarmung (0/8)\nArktischer Gürtel\nArktische Stiefel\nArktischer Brustschutz\nArktische Handschuhe\nArktische Gamaschen\nArktische Schulterpolster\nArktischer Helm\nArktische Handgelenksschützer" }
entries[51571] = { ["name"] = "Arktische Handgelenksschützer", ["text"] = "Wirken in 2 sek.\nReagenzien:\nBoreanisches Leder (12)\nOptionale Reagenzien:\n[] (#48)\nBerufsausbilder:\nLederverarbeitung von Nordend (10)\nKosten:\n30\n\nArktische Handgelenksschützer\nWird beim Anlegen gebunden\nHandgelenk Leder\n3 Rüstung\n+3 [Beweglichkeit oder Intelligenz]+4 Ausdauer\nHaltbarkeit 40 / 40\n28\n\nBoreanische Umarmung (0/8)\nArktischer Gürtel\nArktische Stiefel\nArktischer Brustschutz\nArktische Handschuhe\nArktische Gamaschen\nArktische Schulterpolster\nArktischer Helm\nArktische Handgelenksschützer" }
entries[51572] = { ["name"] = "Arktischer Helm", ["text"] = "Wirken in 2 sek.\nReagenzien:\nBoreanisches Leder (14)\nOptionale Reagenzien:\n[] (#48)\nBerufsausbilder:\nLederverarbeitung von Nordend (10)\nKosten:\n30\n\nArktischer Helm\nWird beim Anlegen gebunden\nKopf Leder\n5 Rüstung\n+5 [Beweglichkeit oder Intelligenz]+7 Ausdauer\nHaltbarkeit 70 / 70\n28\n\nBoreanische Umarmung (0/8)\nArktischer Gürtel\nArktische Stiefel\nArktischer Brustschutz\nArktische Handschuhe\nArktische Gamaschen\nArktische Schulterpolster\nArktischer Helm\nArktische Handgelenksschützer" }
